14	export interface ToolSearchToolPromptProps extends BasePromptElementProps {
15		readonly availableTools: readonly LanguageModelToolInformation[] | undefined;
16		readonly modelFamily: string | undefined;
17	}
18	
19	/**
20	 * Condensed tool search instructions shared across model prompts.
21	 * Renders deferred-tool search guidance when the endpoint supports tool search.
22	 * Self-gates on `endpoint.supportsToolSearch` — returns nothing if disabled.
23	 */
24	export class ToolSearchToolPromptOptimized extends PromptElement<ToolSearchToolPromptProps> {
25		constructor(
26			props: PromptElementProps<ToolSearchToolPromptProps>,
27			@IToolDeferralService private readonly toolDeferralService: IToolDeferralService,
28		) {
29			super(props);
30		}
31	
32		async render(state: void, sizing: PromptSizing) {
33			const endpoint = sizing.endpoint as IChatEndpoint | undefined;
34	
35			const toolSearchEnabled = endpoint
36				? !!endpoint.supportsToolSearch
37				: modelSupportsToolSearch(this.props.modelFamily ?? '');
38	
39			if (!toolSearchEnabled || !this.props.availableTools) {
40				return;
41			}
42	
43			const deferredTools = this.props.availableTools
44				.filter(tool => !this.toolDeferralService.isNonDeferredTool(tool.name))
45				.map(tool => tool.name)
46				.sort();
47	
48			if (deferredTools.length === 0) {
49				return;
50			}
51	
52			return <Tag name='toolSearchInstructions'>
53				You MUST use {CUSTOM_TOOL_SEARCH_NAME} to load deferred tools BEFORE calling them. Calling a deferred tool without loading it first will fail.<br />
54				<br />
55				Describe what capability you need in natural language. The search uses semantic similarity to find the most relevant tools.<br />
56				<br />
57				Do NOT call {CUSTOM_TOOL_SEARCH_NAME} again for a tool already returned by a previous search. If a search returns no matching tools, the tool is not available. Do not retry with different patterns.<br />
58				<br />
59				Available deferred tools (must be loaded before use):<br />
60				{deferredTools.join('\n')}
61			</Tag>;
62		}
63	}
