24	/**
25	 * Prompt component that provides instructions for using the tool search tool
26	 * to load deferred tools before calling them directly.
27	 */
28	class ToolSearchToolPrompt extends PromptElement<ToolSearchToolPromptProps> {
29		constructor(
30			props: PromptElementProps<ToolSearchToolPromptProps>,
31			@IToolDeferralService private readonly toolDeferralService: IToolDeferralService,
32		) {
33			super(props);
34		}
35	
36		async render(state: void, sizing: PromptSizing) {
37			const endpoint = sizing.endpoint as IChatEndpoint | undefined;
38	
39			// Check if tool search is enabled for this model
40			const toolSearchEnabled = endpoint
41				? !!endpoint.supportsToolSearch
42				: modelSupportsToolSearch(this.props.modelFamily ?? '');
43	
44			if (!toolSearchEnabled || !this.props.availableTools) {
45				return;
46			}
47	
48			// Get the list of deferred tools (tools not in the non-deferred set)
49			const deferredTools = this.props.availableTools
50				.filter(tool => !this.toolDeferralService.isNonDeferredTool(tool.name))
51				.map(tool => tool.name)
52				.sort();
53	
54			if (deferredTools.length === 0) {
55				return;
56			}
57	
58			const searchToolName = CUSTOM_TOOL_SEARCH_NAME;
59	
60			return <Tag name='toolSearchInstructions'>
61				Use the {searchToolName} tool to search for deferred tools before calling them.<br />
62				<br />
63				<Tag name='mandatory'>
64					You MUST use the {searchToolName} tool to load deferred tools BEFORE calling them directly.<br />
65					This is a BLOCKING REQUIREMENT - deferred tools listed below are NOT available until you load them using the {searchToolName} tool. Once a tool appears in the results, it is immediately available to call.<br />
66					<br />
67					Why this is required:<br />
68					- Deferred tools are not loaded until discovered via {searchToolName}<br />
69					- Calling a deferred tool without first loading it will fail<br />
70				</Tag>
71				<br />
72				<Tag name='searchQueryGuidance'>
73					Describe what capability you need in natural language. The search uses semantic similarity to find the most relevant tools.<br />
74					<br />
75					Examples:<br />
76					- "create a new file" - finds file creation tools<br />
77					- "run jupyter notebook cell" - finds notebook execution tools<br />
78					- "fetch a web page" - finds web fetching tools<br />
79					- "github pull request" - finds GitHub PR tools<br />
80					<br />
81					Prefer broad queries that cover all related tools in a single search. For example, search "github" to find all GitHub tools at once rather than making separate searches for issues and pull requests. Check the availableDeferredTools list below and use it to inform your query.<br />
82				</Tag>
83				<br />
84				<Tag name='incorrectUsagePatterns'>
85					NEVER do these:<br />
86					- Calling a deferred tool directly without loading it first with {searchToolName}<br />
87					- Calling {searchToolName} again for a tool that was already returned by a previous search<br />
88					- Retrying {searchToolName} repeatedly if it fails or returns no results. If a search returns no matching tools, the tool is not available. Do not retry with different patterns.<br />
89				</Tag>
90				<br />
91				<Tag name='dynamicToolDiscovery'>
92					MCP servers may add or remove tools dynamically during a conversation via tools/list_changed notifications. If you called a tool that may have enabled new tools on an MCP server, search for the new tools — they may now be discoverable even if not listed in the availableDeferredTools list above.<br />
93				</Tag>
94				<br />
95				<Tag name='availableDeferredTools'>
96					Available deferred tools (must be loaded with {searchToolName} before use):<br />
97					{deferredTools.join('\n')}
98				</Tag>
99			</Tag>;
100		}
101	}
